// packages/api/src/services/usuariosServidores.js
import { Router }             from 'express';
import { BaseService }        from './_baseService.js';
import { UsuarioServidorDTO } from '../dto/usuarioServidor.js';
import { HistoricoDTO }       from '../dto/historico.js';

export class UsuariosServidoresService {
    static router() {
        const r = Router();
        r.get('/lookup', UsuariosServidoresService.#lookup);
        r.get('/',       UsuariosServidoresService.#listar);
        r.get('/:id',    UsuariosServidoresService.#obter);
        r.post('/',      UsuariosServidoresService.#criar);
        r.put('/:id',    UsuariosServidoresService.#atualizar);
        r.delete('/:id', UsuariosServidoresService.#excluir);
        return r;
    }

    // ── GET /api/usuarios-servidores?page=1&pageSize=5 ────────────────────────
    static #listar = async (req, res) => {
        try {
            const { page = 1, pageSize = 5, unidadeID } = req.query;
            const offset = (Number(page) - 1) * Number(pageSize);

            const where  = ['excluidoEm IS NULL'];
            const params = [];
            if (unidadeID) { where.push('unidadeID = ?'); params.push(unidadeID); }

            const whereClause = where.join(' AND ');

            const [rows, countRow] = await Promise.all([
                BaseService.query(req.db,
                    `SELECT * FROM usuariosServidores
                     WHERE ${whereClause}
                     ORDER BY nome LIMIT ? OFFSET ?`,
                    [...params, Number(pageSize), offset]),
                BaseService.queryOne(req.db,
                    `SELECT COUNT(*) as total FROM usuariosServidores WHERE ${whereClause}`,
                    params)
            ]);

            return BaseService.ok(res, UsuarioServidorDTO.fromRows(rows), {
                page        : Number(page),
                pageSize    : Number(pageSize),
                totalRecords: countRow.total,
                totalPages  : Math.ceil(countRow.total / Number(pageSize))
            });
        } catch (e) { return UsuariosServidoresService.#erro(res, e); }
    };

    // ── GET /api/usuarios-servidores/lookup ───────────────────────────────────
    static #lookup = async (req, res) => {
        try {
            const rows = await BaseService.query(req.db,
                `SELECT id, nome, login, unidadeID FROM usuariosServidores
                 WHERE excluidoEm IS NULL ORDER BY nome`);
            return BaseService.ok(res, rows);
        } catch (e) { return UsuariosServidoresService.#erro(res, e); }
    };

    // ── GET /api/usuarios-servidores/:id ──────────────────────────────────────
    static #obter = async (req, res) => {
        try {
            const row = await BaseService.queryOne(req.db,
                `SELECT * FROM usuariosServidores WHERE id = ? AND excluidoEm IS NULL`,
                [req.params.id]);
            if (!row) return BaseService.fail(res, 'Usuário não encontrado.', 404);
            return BaseService.ok(res, UsuarioServidorDTO.fromRow(row));
        } catch (e) { return UsuariosServidoresService.#erro(res, e); }
    };

    // ── POST /api/usuarios-servidores ─────────────────────────────────────────
    static #criar = async (req, res) => {
        try {
            const v = BaseService.validateRequest(req.body);
            if (!v.ok) return BaseService.fail(res, v.error, 422);

            const dto    = UsuarioServidorDTO.toInsert(req.body.payload || {}, req.currentUser.id);
            const errors = UsuarioServidorDTO.validate(dto);
            if (errors.length) return BaseService.fail(res, errors.join('; '), 422);

            await BaseService.inTransaction(req.db, async (db) => {
                await BaseService.run(db,
                    `INSERT INTO usuariosServidores
                     (id, unidadeID, funcao, cargo, especialidade, nome, login, matricula, cpf,
                      criadoEm, criadoPor, alteradoEm, alteradoPor,
                      excluidoEm, excluidoPor, exclusaoFisica)
                     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
                    [dto.id, dto.unidadeID, dto.funcao, dto.cargo, dto.especialidade,
                     dto.nome, dto.login, dto.matricula, dto.cpf,
                     dto.criadoEm, dto.criadoPor, null, null, null, null, 0]);

                await BaseService.registrarEvento(db, HistoricoDTO.toEvento({
                    userID    : req.currentUser.id,
                    catalogoID: null,
                    tipo      : 'Backend',
                    acao      : 'CREATE',
                    descricao : `Usuário "${dto.nome}" criado.`,
                    antes     : null,
                    depois    : dto
                }));
            });

            return BaseService.ok(res, UsuarioServidorDTO.fromRow(dto), null, 201);
        } catch (e) { return UsuariosServidoresService.#erro(res, e); }
    };

    // ── PUT /api/usuarios-servidores/:id ──────────────────────────────────────
    static #atualizar = async (req, res) => {
        try {
            const v = BaseService.validateRequest(req.body);
            if (!v.ok) return BaseService.fail(res, v.error, 422);

            const existing = await BaseService.queryOne(req.db,
                `SELECT * FROM usuariosServidores WHERE id = ? AND excluidoEm IS NULL`,
                [req.params.id]);
            if (!existing) return BaseService.fail(res, 'Usuário não encontrado.', 404);

            const dto    = UsuarioServidorDTO.toUpdate(existing, req.body.payload || {}, req.currentUser.id);
            const errors = UsuarioServidorDTO.validate(dto);
            if (errors.length) return BaseService.fail(res, errors.join('; '), 422);

            await BaseService.inTransaction(req.db, async (db) => {
                await BaseService.run(db,
                    `UPDATE usuariosServidores
                     SET unidadeID=?, funcao=?, cargo=?, especialidade=?,
                         nome=?, login=?, matricula=?, cpf=?,
                         alteradoEm=?, alteradoPor=?
                     WHERE id=?`,
                    [dto.unidadeID, dto.funcao, dto.cargo, dto.especialidade,
                     dto.nome, dto.login, dto.matricula, dto.cpf,
                     dto.alteradoEm, dto.alteradoPor, dto.id]);

                await BaseService.registrarEvento(db, HistoricoDTO.toEvento({
                    userID    : req.currentUser.id,
                    catalogoID: null,
                    tipo      : 'Backend',
                    acao      : 'UPDATE',
                    descricao : `Usuário "${dto.nome}" atualizado.`,
                    antes     : UsuarioServidorDTO.fromRow(existing),
                    depois    : dto
                }));
            });

            return BaseService.ok(res, UsuarioServidorDTO.fromRow(dto));
        } catch (e) { return UsuariosServidoresService.#erro(res, e); }
    };

    // ── DELETE /api/usuarios-servidores/:id ───────────────────────────────────
    static #excluir = async (req, res) => {
        try {
            const existing = await BaseService.queryOne(req.db,
                `SELECT * FROM usuariosServidores WHERE id = ? AND excluidoEm IS NULL`,
                [req.params.id]);
            if (!existing) return BaseService.fail(res, 'Usuário não encontrado.', 404);

            const agora = BaseService.now();

            await BaseService.inTransaction(req.db, async (db) => {
                await BaseService.run(db,
                    `UPDATE usuariosServidores
                     SET excluidoEm=?, excluidoPor=? WHERE id=?`,
                    [agora, req.currentUser.id, existing.id]);

                await BaseService.registrarEvento(db, HistoricoDTO.toEvento({
                    userID    : req.currentUser.id,
                    catalogoID: null,
                    tipo      : 'Backend',
                    acao      : 'DELETE',
                    descricao : `Usuário "${existing.nome}" excluído.`,
                    antes     : UsuarioServidorDTO.fromRow(existing),
                    depois    : null
                }));
            });

            return res.status(204).send();
        } catch (e) { return UsuariosServidoresService.#erro(res, e); }
    };

    // ── Error handler local ───────────────────────────────────────────────────
    static #erro(res, e) {
        console.error(`[${BaseService.now()}] [UsuariosServidoresService]`, e.message);
        return BaseService.fail(res, 'Erro interno do servidor.', 500);
    }
}